import React, { useState, useEffect, useRef, useCallback } from 'react';
import { getTelegramUser, apiRequest } from '../api';

interface Message {
  id: string;
  text: string;
  sender_type: 'user' | 'assistant';
  created_at: string;
  thread_id: string;
}

interface Thread {
  id: string;
  title?: string;
  created_at: string;
  message_count: number;
}

const TelegramChat: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);

  // Принудительная разблокировка каждые 10 секунд если sending = true
  useEffect(() => {
    if (sending) {
      console.log('[SEND] 🔒 Поле заблокировано, запускаем таймер разблокировки...');
      const timeout = setTimeout(() => {
        console.log('[SEND] ⏰ Автоматическая разблокировка через 10 секунд');
        setSending(false);
      }, 10000);

      return () => clearTimeout(timeout);
    }
  }, [sending]);

  // Автоматическое обновление сообщений каждые 5 секунд
  const telegramUser = getTelegramUser();
  const telegramUserId = (telegramUser as any)?.id as number | undefined;
  useEffect(() => {
    console.log('[AUTO_UPDATE] 🚀 Запускаем автоматическое обновление сообщений');
    const interval = setInterval(async () => {
      if (!telegramUserId || sending) return; // Не обновляем если отправка в процессе

      try {
        const recentResp = await apiRequest(`/messages/recent?limit=50&offset=0&_t=${Date.now()}`, 'GET', null, {
          'X-Telegram-User-ID': String(telegramUserId)
        });

        if (recentResp.status === 'success') {
          const newMessages = (recentResp.messages || []) as any[];
          if (newMessages.length > messages.length) {
            console.log('[AUTO_UPDATE] 📥 Найдены новые сообщения:', newMessages.length - messages.length);
            const sorted = newMessages.reverse();
            setMessages(sorted);
            setOffset(50);
            setHasMoreMessages(newMessages.length === 50);

            // Скроллим только если пользователь был внизу чата
            const messagesContainer = messagesContainerRef.current;
            if (messagesContainer) {
              const isAtBottom = messagesContainer.scrollHeight - messagesContainer.scrollTop <= messagesContainer.clientHeight + 100;
              if (isAtBottom) {
                setTimeout(() => scrollToBottom(), 100);
              }
            }
          }
        }
      } catch (error) {
        console.warn('[AUTO_UPDATE] Ошибка автоматического обновления:', error);
      }
    }, 5000); // Каждые 5 секунд

    return () => {
      console.log('[AUTO_UPDATE] 🛑 Останавливаем автоматическое обновление');
      clearInterval(interval);
    };
  }, [telegramUserId, messages.length, sending]);
  const [loadingMore, setLoadingMore] = useState(false);
  const [hasMoreMessages, setHasMoreMessages] = useState(true);
  const [offset, setOffset] = useState(0);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);

  // перемещено выше для корректного порядка объявления

  // Убираем автоматический скролл, используем кнопку

  useEffect(() => {
    console.log('[INIT] 🚀 Инициализация TelegramChat');
    console.log('[INIT] 📊 Начальные состояния:', { sending, loading, loadingMore });
    loadInitialMessages().then(() => {
      // Скролл к низу только при первом входе в приложение
      console.log('[INIT] 📜 Скроллим к последнему сообщению при входе...');
      setTimeout(() => scrollToBottom(), 500);
    });
  }, []);

  // Логируем изменения состояния sending
  useEffect(() => {
    console.log('[STATE] 🔄 sending изменился на:', sending);
  }, [sending]);

  // Убираем автопрокрутку - будем контролировать вручную

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const loadInitialMessages = useCallback(async () => {
    if (!telegramUserId) {
      console.warn('[INIT] Нет Telegram ID — прекращаем загрузку');
      return;
    }
    setLoading(true);
    try {
      console.log('[LOAD] 📥 Загружаем последние сообщения...');
      console.log('[LOAD] 👤 Пользователь для загрузки:', telegramUser);
      console.log('[LOAD] 🆔 User ID для загрузки:', telegramUser?.id?.toString() ?? 'undefined');
      
      // Проверяем localStorage
      console.log('[LOAD] 💾 localStorage сообщения:', localStorage.getItem('messages'));
      console.log('[LOAD] 💾 sessionStorage сообщения:', sessionStorage.getItem('messages'));
      
      // Очищаем localStorage на всякий случай
      localStorage.removeItem('messages');
      sessionStorage.removeItem('messages');
      
      // Добавляем timestamp для избежания кэширования
      const timestamp = Date.now();
      const url = `/messages/recent?limit=50&offset=0&_t=${timestamp}`;
      console.log('[LOAD] 🌐 Запрос URL (последние 50):', url);
      
      const loadHeaders = {
        'X-Telegram-User-ID': String(telegramUserId)
      };
      console.log('[LOAD] 📋 Заголовки запроса:', loadHeaders);
      
      const response = await apiRequest(url, 'GET', null, loadHeaders);
      
      console.log('[LOAD] ПОЛНЫЙ ответ сервера:', JSON.stringify(response, null, 2));
      console.log('[LOAD] 🔍 ДЕТАЛЬНЫЙ АНАЛИЗ:');
      console.log('[LOAD] 📊 Количество сообщений в ответе:', response.messages?.length || 0);
      
      if (response.messages && response.messages.length > 0) {
        console.log('[LOAD] 📅 Первое сообщение (самое новое):', response.messages[0]);
        console.log('[LOAD] 📅 Последнее сообщение (самое старое):', response.messages[response.messages.length - 1]);
        console.log('[LOAD] 🔤 Тексты сообщений:');
        response.messages.forEach((msg: any, idx: number) => {
          console.log(`[LOAD]    ${idx + 1}. [${msg.sender_type}] ${msg.text.substring(0, 50)}... (${msg.created_at})`);
        });
      }
      
      if (response.status === 'success') {
        const sortedMessages = (response.messages || []).reverse();
        console.log('[LOAD] ✅ Загружено сообщений:', sortedMessages.length);
        setMessages(sortedMessages);
        setOffset(50);
        setHasMoreMessages(response.messages.length === 50);
      } else {
        console.error('[LOAD] Ошибка в ответе:', response);
        setMessages([]);
      }
    } catch (error) {
      console.error('[LOAD] Ошибка загрузки сообщений:', error);
      setMessages([]);
    } finally {
      setLoading(false);
    }
  }, [telegramUser]);

  const loadMoreMessages = async () => {
    if (loadingMore || !hasMoreMessages || !telegramUserId) return;
    
    setLoadingMore(true);
    
    try {
      console.log('[LOAD MORE] Загружаем сообщения с offset:', offset);
      const response = await apiRequest(`/messages/recent?limit=30&offset=${offset}`, 'GET', null, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      if (response.status === 'success') {
        const newMessages = (response.messages || []).reverse();
        console.log('[LOAD MORE] Получено сообщений:', newMessages.length);
        
        if (newMessages.length > 0) {
          setMessages(prev => [...newMessages, ...prev]);
          setOffset(prev => prev + newMessages.length);
          setHasMoreMessages(response.messages.length === 30);
        } else {
          setHasMoreMessages(false);
        }
      }
    } catch (error) {
      console.error('Ошибка загрузки дополнительных сообщений:', error);
    } finally {
      setLoadingMore(false);
    }
  };

  // Убрали автоматический скролл - теперь используем кнопку

  const sendMessage = async () => {
    if (!telegramUserId) {
      alert('Не удаётся определить Telegram ID. Откройте мини‑приложение из Telegram.');
      return;
    }
    if (!newMessage.trim() || sending) {
      console.log('[SEND] Отменено: пустое сообщение или уже отправляется', { newMessage: newMessage.trim(), sending });
      return;
    }

    console.log('[SEND] Начинаем отправку...');
    setSending(true);
    const userMessage = newMessage;
    setNewMessage('');

    // Добавляем сообщение пользователя в UI сразу
    const tempUserMessage: Message = {
      id: 'temp-' + Date.now(),
      text: userMessage,
      sender_type: 'user',
      created_at: new Date().toISOString(),
      thread_id: 'main-chat'
    };
    setMessages(prev => [...prev, tempUserMessage]);

    try {
      console.log('[SEND] 📤 Отправляем сообщение:', userMessage);
      console.log('[SEND] 👤 Пользователь для отправки:', telegramUser?.id);
      
      const response = await apiRequest('/chat/send', 'POST', {
        message: userMessage,
        thread_id: null // Пусть создается автоматически
      }, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      console.log('[SEND] 📨 Полный ответ отправки:', JSON.stringify(response, null, 2));
      
      console.log('[SEND] Ответ сервера:', response);
      
      if (response.status === 'success') {
        console.log('[SEND] ✅ Успешно отправлено! Обновляем тред...');

        // Всегда обновляем сообщения после отправки, независимо от thread_id
        try {
          console.log('[SEND] 🔄 Обновляем сообщения после отправки...');
          const recentResp = await apiRequest(`/messages/recent?limit=50&offset=0&_t=${Date.now()}`, 'GET', null, {
            'X-Telegram-User-ID': String(telegramUserId)
          });

          if (recentResp.status === 'success') {
            const newMessages = (recentResp.messages || []) as any[];
            console.log('[SEND] 📥 Получено сообщений после отправки:', newMessages.length);

            // Убеждаемся что новые сообщения включают наше отправленное
            if (newMessages.length > 0) {
              const sorted = newMessages.reverse();
              setMessages(sorted);
              setOffset(50);
              setHasMoreMessages(newMessages.length === 50);

              // Скроллим к последнему сообщению
              setTimeout(() => scrollToBottom(), 100);

              console.log('[SEND] ✅ Сообщения обновлены успешно');
            } else {
              console.warn('[SEND] ⚠️ Получен пустой список сообщений');
            }
          } else {
            console.error('[SEND] ❌ Ошибка при получении сообщений:', recentResp);
          }
        } catch (updateError) {
          console.error('[SEND] ❌ Ошибка обновления сообщений:', updateError);
          // В случае ошибки просто перезагружаем все сообщения
          await loadInitialMessages();
        }
      } else {
        setMessages(prev => prev.filter(m => m.id !== tempUserMessage.id));
        console.error('[SEND] Ошибка в ответе:', response);
        alert(`Ошибка отправки: ${response.message || 'Неизвестная ошибка'}`);
      }
    } catch (error) {
      setMessages(prev => prev.filter(m => m.id !== tempUserMessage.id));
      console.error('[SEND] Ошибка отправки сообщения:', error);
      alert(`Ошибка отправки сообщения: ${error}`);
    } finally {
      console.log('[SEND] Разблокируем интерфейс...');
      setSending(false);
      console.log('[SEND] Интерфейс разблокирован');
    }
  };

  const deleteMessage = async (messageId: string) => {
    if (!confirm('Удалить это сообщение?')) return;

    try {
      const response = await apiRequest(`/messages/${messageId}`, 'DELETE', null, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      if (response.status === 'success') {
        setMessages(prev => prev.filter(m => m.id !== messageId));
      } else {
        alert('Ошибка удаления');
      }
    } catch (error) {
      console.error('Ошибка удаления сообщения:', error);
      alert('Ошибка удаления сообщения');
    }
  };

  const clearAllMessages = async () => {
    if (!confirm('Очистить всю историю сообщений? Это действие необратимо!')) return;
    
    try {
      const response = await apiRequest('/messages/clear-all', 'DELETE', null, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      if (response.status === 'success') {
        setMessages([]);
        alert(`Удалено ${response.deleted_count} сообщений`);
      }
    } catch (error) {
      console.error('Ошибка очистки сообщений:', error);
      alert('Ошибка очистки сообщений');
    }
  };

  const syncWithTelegram = async () => {
    if (!confirm('Отправить всю историю в Telegram? Это может занять время при большом количестве сообщений.')) return;
    
    try {
      setLoading(true);
      const response = await apiRequest('/messages/sync-to-telegram', 'POST', null, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      if (response.status === 'success') {
        alert(`✅ Синхронизация завершена! Отправлено ${response.sent_count} сообщений в Telegram.`);
      } else {
        alert(`⚠️ Синхронизация завершена с предупреждениями: ${response.message}`);
      }
    } catch (error) {
      console.error('Ошибка синхронизации:', error);
      alert('Ошибка синхронизации с Telegram');
    } finally {
      setLoading(false);
    }
  };

  const formatTime = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleTimeString('ru-RU', { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    
    if (date.toDateString() === today.toDateString()) {
      return 'Сегодня';
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Вчера';
    } else {
      return date.toLocaleDateString('ru-RU', { 
        day: '2-digit', 
        month: '2-digit',
        year: 'numeric'
      });
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  // Telegram-стиль стили
  const telegramStyles = {
    container: {
      backgroundColor: '#17212B',
      color: '#FFFFFF',
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column' as const,
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    },
    header: {
      backgroundColor: '#242F3D',
      padding: '12px 16px',
      borderBottom: '1px solid #3E546A',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between'
    },
    headerTitle: {
      fontSize: '18px',
      fontWeight: '500',
      color: '#FFFFFF',
      margin: 0
    },
    headerSubtitle: {
      fontSize: '14px',
      color: '#8E8E93',
      margin: '2px 0 0 0'
    },
    messagesContainer: {
      flex: 1,
      padding: '8px',
      overflowY: 'auto' as const,
      backgroundColor: '#17212B'
    },
    messageWrapper: {
      display: 'flex',
      marginBottom: '8px',
      alignItems: 'flex-end'
    },
    messageUserWrapper: {
      justifyContent: 'flex-end'
    },
    messageBubble: {
      maxWidth: '80%',
      padding: '8px 12px',
      borderRadius: '12px',
      position: 'relative' as const,
      wordWrap: 'break-word' as const
    },
    messageBubbleUser: {
      backgroundColor: '#0088CC',
      color: '#FFFFFF',
      borderBottomRightRadius: '4px'
    },
    messageBubbleBot: {
      backgroundColor: '#232E3C',
      color: '#FFFFFF',
      borderBottomLeftRadius: '4px'
    },
    messageText: {
      fontSize: '16px',
      lineHeight: '1.4',
      margin: 0
    },
    messageTime: {
      fontSize: '12px',
      opacity: 0.7,
      marginTop: '2px',
      textAlign: 'right' as const
    },
    messageDeleteBtn: {
      position: 'absolute' as const,
      top: '-8px',
      right: '-8px',
      backgroundColor: '#FF4757',
      color: '#FFFFFF',
      border: 'none',
      borderRadius: '50%',
      width: '20px',
      height: '20px',
      fontSize: '12px',
      cursor: 'pointer',
      opacity: 0,
      transition: 'opacity 0.2s'
    },
    inputContainer: {
      backgroundColor: '#242F3D',
      padding: '12px 16px',
      borderTop: '1px solid #3E546A',
      display: 'flex',
      gap: '8px',
      alignItems: 'flex-end'
    },
    messageInput: {
      flex: 1,
      backgroundColor: '#17212B',
      border: '1px solid #3E546A',
      borderRadius: '20px',
      padding: '8px 16px',
      color: '#FFFFFF',
      fontSize: '16px',
      resize: 'none' as const,
      outline: 'none',
      minHeight: '20px',
      maxHeight: '120px'
    },
    sendButton: {
      backgroundColor: '#0088CC',
      color: '#FFFFFF',
      border: 'none',
      borderRadius: '50%',
      width: '36px',
      height: '36px',
      fontSize: '16px',
      cursor: 'pointer',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    },
    newChatButton: {
      backgroundColor: 'transparent',
      color: '#0088CC',
      border: 'none',
      fontSize: '14px',
      cursor: 'pointer',
      padding: '4px 8px'
    },
    dateHeader: {
      textAlign: 'center' as const,
      margin: '16px 0 8px 0',
      fontSize: '13px',
      color: '#8E8E93',
      backgroundColor: '#242F3D',
      padding: '4px 12px',
      borderRadius: '12px',
      display: 'inline-block',
      position: 'relative' as const,
      left: '50%',
      transform: 'translateX(-50%)'
    },
    reactionsPanel: {
      display: 'flex',
      gap: '4px',
      marginTop: '4px',
      opacity: 0.7,
      transition: 'opacity 0.2s'
    },
    reactionBtn: {
      backgroundColor: 'transparent',
      border: 'none',
      fontSize: '16px',
      cursor: 'pointer',
      padding: '2px 4px',
      borderRadius: '4px',
      transition: 'background-color 0.2s'
    },
    loadMoreButton: {
      backgroundColor: '#242F3D',
      color: '#0088CC',
      border: '1px solid #3E546A',
      borderRadius: '20px',
      padding: '8px 16px',
      fontSize: '14px',
      fontWeight: '500',
      cursor: 'pointer',
      transition: 'all 0.2s',
      ':hover': {
        backgroundColor: '#3E546A'
      },
      ':disabled': {
        opacity: 0.5,
        cursor: 'not-allowed'
      }
    }
  };

  // Если нет Telegram ID (веб без авторизации) — показываем экран входа
  if (!telegramUserId) {
    return (
      <div style={telegramStyles.container}>
        <div style={telegramStyles.header}>
          <div>
            <h1 style={telegramStyles.headerTitle}>💬 Чат в приложении</h1>
            <p style={telegramStyles.headerSubtitle}>Требуется вход через Telegram</p>
          </div>
        </div>
        <div style={{display:'flex',alignItems:'center',justifyContent:'center',flex:1,flexDirection:'column',color:'#8E8E93'}}> 
          <div style={{fontSize:24, marginBottom:12}}>Приложение доступно после входа</div>
          <button onClick={() => { try { window.location.hash = '#/webauth'; } catch { window.location.replace('/#\/webauth'); } }} style={{padding:'10px 16px', borderRadius:12, border:'1px solid #3E546A', background:'#242F3D', color:'#fff', cursor:'pointer'}}>Войти через Telegram</button>
        </div>
      </div>
    );
  }

  return (
    <div style={telegramStyles.container}>
      {/* Header */}
      <div style={telegramStyles.header}>
        <div>
          <h1 style={telegramStyles.headerTitle}>
            💬 Чат в приложении
          </h1>
          <p style={telegramStyles.headerSubtitle}>
            {messages.length} сообщений • 👤 User: {telegramUser?.id} • v2.1-{Date.now().toString().slice(-6)}
            {sending && ' • 🔒 БЛОКИРОВКА'}
          </p>
        </div>
        <div style={{ display: 'flex', gap: '8px' }}>
          <button
            onClick={syncWithTelegram}
            style={{ ...telegramStyles.newChatButton, color: '#00C851' }}
            disabled={loading}
            title="Отправить историю в Telegram"
          >
            🔄 Синхронизация
          </button>
          <button
            onClick={clearAllMessages}
            style={telegramStyles.newChatButton}
          >
            🗑️ Очистить всё
          </button>
          <button
            onClick={() => {
              console.log('[DEBUG] 🔄 ПРИНУДИТЕЛЬНАЯ ПЕРЕЗАГРУЗКА СООБЩЕНИЙ');
              setMessages([]);
              setLoading(true);
              setOffset(0);
              setHasMoreMessages(true);
              loadInitialMessages();
            }}
            style={{ ...telegramStyles.newChatButton, color: '#007AFF' }}
            title="Принудительно перезагрузить сообщения"
          >
            🔄
          </button>
          {/* dev-кнопка смены UserID удалена */}
          {sending && (
            <button 
              onClick={() => {
                console.log('[DEBUG] 🔓 Экстренная разблокировка интерфейса');
                setSending(false);
                setLoading(false);
                setLoadingMore(false);
                console.log('[DEBUG] ✅ Все состояния сброшены');
              }} 
              style={{...telegramStyles.newChatButton, color: '#FF3B30', fontWeight: 'bold'}}
              title="Экстренная разблокировка поля ввода"
            >
              🚨 РАЗБЛОКИРОВАТЬ
            </button>
          )}
        </div>
      </div>

      {/* Messages */}
      <div ref={messagesContainerRef} style={telegramStyles.messagesContainer}>
        {/* Кнопка "Загрузить еще" для старых сообщений */}
        {!loading && hasMoreMessages && (
          <div style={{ textAlign: 'center', padding: '12px' }}>
            <button
              onClick={loadMoreMessages}
              disabled={loadingMore}
              style={telegramStyles.loadMoreButton}
            >
              {loadingMore ? '⏳ Загрузка...' : '⬆️ Загрузить старые сообщения'}
            </button>
          </div>
        )}
        
        {loading ? (
          <div style={{ textAlign: 'center', padding: '20px', color: '#8E8E93' }}>
            Загрузка сообщений...
          </div>
        ) : messages.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '40px', color: '#8E8E93' }}>
            <div style={{ fontSize: '48px', marginBottom: '16px' }}>💭</div>
            <p>Пока нет сообщений</p>
            <p style={{ fontSize: '14px' }}>Начните диалог, отправив первое сообщение</p>
          </div>
        ) : (
          messages.map((message, index) => {
            // Показываем дату если это первое сообщение или дата отличается от предыдущего
            const showDate = index === 0 || 
              formatDate(message.created_at) !== formatDate(messages[index - 1]?.created_at);
            
            return (
              <React.Fragment key={message.id}>
                {showDate && (
                  <div style={telegramStyles.dateHeader}>
                    {formatDate(message.created_at)}
                  </div>
                )}
                <div
                  style={{
                    ...telegramStyles.messageWrapper,
                    ...(message.sender_type === 'user' ? telegramStyles.messageUserWrapper : {})
                  }}
                >
                  <div
                    style={{
                      ...telegramStyles.messageBubble,
                      ...(message.sender_type === 'user' 
                        ? telegramStyles.messageBubbleUser 
                        : telegramStyles.messageBubbleBot
                      )
                    }}
                    onMouseEnter={(e) => {
                      const deleteBtn = e.currentTarget.querySelector('.delete-btn') as HTMLElement;
                      if (deleteBtn) deleteBtn.style.opacity = '1';
                    }}
                    onMouseLeave={(e) => {
                      const deleteBtn = e.currentTarget.querySelector('.delete-btn') as HTMLElement;
                      if (deleteBtn) deleteBtn.style.opacity = '0';
                    }}
                  >
                    <button
                      className="delete-btn"
                      onClick={() => deleteMessage(message.id)}
                      style={telegramStyles.messageDeleteBtn}
                      title="Удалить сообщение"
                    >
                      ×
                    </button>
                    <p style={telegramStyles.messageText}>
                      {message.text}
                    </p>
                    
                    {/* Панель реакций */}
                    <div style={telegramStyles.reactionsPanel}>
                      <button style={telegramStyles.reactionBtn} title="Лайк">👍</button>
                      <button style={telegramStyles.reactionBtn} title="Дизлайк">👎</button>
                      <button style={telegramStyles.reactionBtn} title="Сердце">❤️</button>
                      <button style={telegramStyles.reactionBtn} title="Смех">😂</button>
                      <button style={telegramStyles.reactionBtn} title="Удивление">😮</button>
                      <button style={telegramStyles.reactionBtn} title="Грусть">😢</button>
                    </div>
                    
                    <div style={telegramStyles.messageTime}>
                      {formatTime(message.created_at)}
                    </div>
                  </div>
                </div>
              </React.Fragment>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div style={telegramStyles.inputContainer}>
        <textarea
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder={sending ? "🔒 Поле заблокировано..." : "Введите сообщение..."}
          style={{
            ...telegramStyles.messageInput,
            backgroundColor: sending ? '#2A1B1B' : '#17212B',
            borderColor: sending ? '#FF3B30' : '#3E546A'
          }}
          disabled={sending}
          rows={1}
        />
        <button
          onClick={sendMessage}
          disabled={!newMessage.trim() || sending}
          style={{
            ...telegramStyles.sendButton,
            opacity: !newMessage.trim() || sending ? 0.5 : 1
          }}
        >
          {sending ? '⏳' : '📤'}
        </button>
      </div>
    </div>
  );
};

export default TelegramChat;
